import os
from reference import Task
try:
    import fastgcm
except Exception:
    fastgcm = None

_NT = 8

class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]; nonce = problem["nonce"]
        aad = problem.get("associated_data") or b""
        if fastgcm is not None and len(key) == 16 and len(nonce) == 12:
            r = fastgcm.encrypt(key, nonce, problem["plaintext"], aad, _NT)
            if r is not None:
                return {"ciphertext": r[0], "tag": r[1]}
        return Task().solve(problem)

