    __m128i nonce_blk; uint32_t ctr0;
    const uint8_t *in; uint8_t *out; size_t len; /* len multiple of 16 except last chunk */
    __m128i ghash;
} job_t;

static void *worker(void *arg){
    job_t *j = (job_t*)arg;
    const __m128i *rk=j->rk, *hp=j->hp;
    __m128i rk0=rk[0],rk1=rk[1],rk2=rk[2],rk3=rk[3],rk4=rk[4],rk5=rk[5],rk6=rk[6],rk7=rk[7],rk8=rk[8],rk9=rk[9],rk10=rk[10];
    __m128i H1=hp[0],H2=hp[1],H3=hp[2],H4=hp[3],H5=hp[4],H6=hp[5],H7=hp[6],H8=hp[7];
    __m128i Y = _mm_setzero_si128();
    uint32_t ctr = j->ctr0;
    const uint8_t *in=j->in; uint8_t *out=j->out; size_t len=j->len;
    __m128i nb = j->nonce_blk;
    size_t i=0;
