        R(rk1) R(rk2) R(rk3) R(rk4) R(rk5) R(rk6) R(rk7) R(rk8) R(rk9)
        for(int k=0;k<8;k++){ b[k]=_mm_aesenclast_si128(b[k],rk10);
            b[k]=_mm_xor_si128(b[k],_mm_loadu_si128((const __m128i*)(in+i+16*k)));
            _mm_storeu_si128((__m128i*)(out+i+16*k), b[k]); }
