        clmul_acc(_mm_xor_si128(Y,_mm_shuffle_epi8(b[0],BSWAP)),H8,&lo,&mid,&hi);
        clmul_acc(_mm_shuffle_epi8(b[1],BSWAP),H7,&lo,&mid,&hi);
        clmul_acc(_mm_shuffle_epi8(b[2],BSWAP),H6,&lo,&mid,&hi);
        clmul_acc(_mm_shuffle_epi8(b[3],BSWAP),H5,&lo,&mid,&hi);
        clmul_acc(_mm_shuffle_epi8(b[4],BSWAP),H4,&lo,&mid,&hi);
        clmul_acc(_mm_shuffle_epi8(b[5],BSWAP),H3,&lo,&mid,&hi);
