    uint8_t tb[16]; _mm_storeu_si128((__m128i*)tb,tag);
    PyBuffer_Release(&key);PyBuffer_Release(&nonce);PyBuffer_Release(&pt);PyBuffer_Release(&aad);
    PyObject *t = PyBytes_FromStringAndSize((char*)tb,16);
    return Py_BuildValue("(NN)",ct,t);
}

